public void getMax() {
    int templength = currentyvalues.length;
    double[] temparray = new double[templength];
    for (int i = 0; i  templength; i++) {
        temparray[i] = currentyvalues[i];
    }
    Arrays.sort(temparray);
    max = temparray[templength - 1];
}

