public TokenBuffer(LexicalAnalyzer input, int depth) throws TokenException {
    this.input = input;
    this.depth = depth;
    buffer = new Token[depth];
    for (int i = 0; i  depth; i++) {
        buffer[i] = input.read();
    }
}

