private static double[] getFirstHalfArray(double[] condAndUncond) {
    int count = (condAndUncond.length) / 2;
    double[] returnArray = new double[count];
    for (int a = 0; a  count; a++) {
        returnArray[a] = condAndUncond[a];
    }
    return returnArray;
}

