public byte[] extractArray(byte[] src, int start, int end) {
    int len = end - start;
    if (len  0) return null;
    byte[] ret = new byte[len];
    for (int i = 0; i  len; i++) {
        ret[i] = src[start + i];
    }
    return ret;
}

