        temparray[i] = currentyvalues[i];
    }
    Arrays.sort(temparray);
    max = temparray[templength - 1];
}

protected byte[] getResult() {
    byte[] result = new byte[DIGEST_LENGTH];
    encryptBlock(checksum, 0);
    for (int i = 0; i  BLOCK_LENGTH; i++) {
        result[i] = work[i];
    }
    return result;
}

